// Recuperer l'audio depuis le webhook.
// L'extension >= 1.3.0 envoie en multipart/form-data (champ "audio").
// Les versions anterieures envoyaient un JSON base64 (champ body.audio).
const input = $input.first();
let audioBuffer;
let timestamp;
let mode;

if (input.binary && input.binary.audio) {
  // Multipart : n8n a deja attache le fichier sous binary.audio
  audioBuffer = await this.helpers.getBinaryDataBuffer(0, 'audio');
  timestamp = input.json.body && input.json.body.timestamp
    ? input.json.body.timestamp
    : new Date().toISOString();
  mode = input.json.body && input.json.body.mode;
} else if (input.json.body && input.json.body.audio) {
  // Legacy : base64 dans le JSON
  audioBuffer = Buffer.from(input.json.body.audio, 'base64');
  timestamp = input.json.body.timestamp || new Date().toISOString();
  mode = input.json.body.mode;
} else {
  throw new Error('Aucune donnee audio recue (ni binary.audio ni body.audio)');
}

// Mode de traitement : 'prompt' (reecriture) ou 'transcript' (nettoyage leger).
// Defaut retro-compatible : 'prompt'.
mode = mode === 'transcript' ? 'transcript' : 'prompt';

return [{
  json: {
    timestamp,
    mode,
    audioSizeKB: Math.round(audioBuffer.length / 1024)
  },
  binary: {
    data: await this.helpers.prepareBinaryData(
      audioBuffer,
      'recording.mp3',
      'audio/mpeg'
    )
  }
}];

// Verifier si la transcription a reussi
const sttResponse = $input.first().json;

if (!sttResponse.text && !sttResponse.transcription) {
  throw new Error('Echec de la transcription: ' + JSON.stringify(sttResponse));
}

const transcribedText = sttResponse.text || sttResponse.transcription || '';

return [{
  json: {
    text: transcribedText.trim()
  }
}];

