// Extraire le texte nettoye de la reponse Mistral
const response = $input.first().json;

let cleanedText = '';

if (response.choices && response.choices[0] && response.choices[0].message) {
  cleanedText = response.choices[0].message.content;
} else {
  throw new Error('Format de reponse Mistral inattendu: ' + JSON.stringify(response));
}

// Nettoyer le texte
cleanedText = cleanedText.trim();

// Recuperer le texte original et le mode de traitement
const originalText = $('Check STT Result').first().json.text || '';
const mode = $('Prepare Audio').first().json.mode || 'prompt';

return [{
  json: {
    cleanedText: cleanedText,
    originalText: originalText,
    mode: mode,
    timestamp: new Date().toISOString()
  }
}];
